#include "../src/core/hex_bookmarks.h"
#include "../src/core/structured_compare.h"
#include "../src/core/decimal_compare.h"
#include "../src/core/line_merge.h"
#include "../src/core/workspace_session.h"
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace simple_editor::core;
int RunDiscoveryTests(const std::filesystem::path& root) {
    int failures = 0; const auto check = [&](bool ok,const wchar_t* label) { std::wcout << (ok ? L"PASS: " : L"FAIL: ") << label << L'\n'; if (!ok) ++failures; };
    std::wstring error,value; const std::wstring unicode = L"header\n\u4E2D\u6587\U0001F680"; check(DecodeSetting(EncodeSetting(unicode),&value) && value == unicode && !DecodeSetting(L"00ZZ",&value),L"feature settings retain Unicode/newlines and reject malformed encoded values");
    const auto path = root / L"bookmarks.bin"; { std::ofstream output(path,std::ios::binary); output << "12345678"; } BinaryDocument document; document.Open(path.wstring(),&error); HexBookmarks bookmarks; InspectFile(path,&bookmarks.source,&error); NamedHexRange range; range.name = L"Header"; range.comment = unicode; range.offset = 1; range.length = 3;
    check(bookmarks.Add(range,document.Size(),&error) && bookmarks.Matches(document),L"named Hex ranges bind to the exact source file state"); HexBookmarks restored; check(restored.Load(bookmarks.Save(true),document.Size(),&error) && restored.ranges[0].comment == unicode && restored.Matches(document),L"Hex range settings round-trip physical offsets, color and comments");
    range.offset = UINT64_MAX; check(!bookmarks.Add(range,document.Size(),&error),L"Hex bookmark address overflow and beyond-EOF ranges are rejected"); bookmarks.stale = true; check(!bookmarks.Matches(document) && restored.Load(bookmarks.Save(false),document.Size(),&error) && restored.stale,L"stale and unsaved range versions cannot silently become navigable after restore");
    bool equal = false; check(DecimalWithin(L"9007199254740993",L"9007199254740992",L"0.5",&equal) && !equal && DecimalWithin(L"0.1",L"0.1001",L"0.0001",&equal) && equal,L"decimal tolerances retain exact integers and inclusive fractional boundaries"); check(DecimalWithin(L"-1e2",L"100",L"200",&equal) && equal && !DecimalWithin(L"1",L"2",L"-1",&equal) && !DecimalWithin(L"NaN",L"NaN",L"0",&equal),L"decimal arithmetic handles opposite signs and rejects invalid/negative tolerances");
    TableCompareOptions options; check(ParseTableOptions(L"header=yes\n1,2,key\n2,1,0.01",&options,&error),L"table settings accept explicit headers, key mapping and numeric tolerance"); StructuredComparison result; std::atomic_bool cancel{false}; const std::wstring left = L"id,value\na,1.00\nb,2\n",right = L"value,id\n2.005,b\n1,a\n";
    check(CompareStructured(left,right,StructuredFormat::Csv,cancel,&result,&error,options) && !result.different,L"keyed CSV comparison aligns reordered records and mapped columns with exact tolerance"); check(CompareStructured(left,L"value,id\n2.02,b\n1,a\n",StructuredFormat::Csv,cancel,&result,&error,options) && result.different == 1,L"mapped numeric values outside tolerance report an exact field difference");
    check(CompareStructured(left,L"value,id\n1,a\n2,a\n",StructuredFormat::Csv,cancel,&result,&error,options) && result.different >= 1 && result.rows[0].state.find(L"Ambiguous") != std::wstring::npos,L"duplicate table keys are explicit ambiguities rather than arbitrary pairings"); check(!ParseTableOptions(L"1,1,key\n1,2,text",&options,&error) && !ParseTableOptions(L"1,1,-0.1",&options,&error),L"duplicate column mappings and invalid tolerances are rejected");
    check(CompareStructured(L"a\tb\n1\tx\n",L"a\tb\n1\ty\n",StructuredFormat::Tsv,cancel,&result,&error) && result.different == 1,L"default TSV positional semantics remain unchanged"); const auto previous = result.different; cancel = true; check(!CompareStructured(left,right,StructuredFormat::Csv,cancel,&result,&error) && result.different == previous,L"cancelled structured work preserves previously adopted results"); cancel = false;
    LineOptions rules; check(ParseTextRules(L"ignore-blank=yes\nignore-prefix=DEBUG\nmask-timestamps=yes",&rules.rules,&error),L"bounded text rules accept explicit blank/prefix/timestamp settings"); TextMergeModel model; const std::wstring a = L"2026-01-01 12:00:00 value=7\n\nDEBUG one\nend\n",b = L"2026-02-02 13:02:01 value=7\nDEBUG two\nend\n"; check(BuildTextMerge(L"",a,b,false,rules,cancel,&model,&error) && std::none_of(model.blocks.begin(),model.blocks.end(),[](const auto& block) { return block.changed && block.important; }),L"ignored blank/prefix lines and timestamp values do not become important differences"); check(RenderMerge(model) == a && model.left[0].text == L"2026-01-01 12:00:00 value=7",L"comparison normalization retains raw sources and default merge output"); check(BuildTextMerge(L"",a,L"2026-02-02 13:02:01 value=8\nend\n",false,rules,cancel,&model,&error) && std::any_of(model.blocks.begin(),model.blocks.end(),[](const auto& block) { return block.changed && block.important; }),L"timestamp masks do not suppress unrelated value changes"); check(!ParseTextRules(L"ignore-prefix=",&rules.rules,&error) && !ParseTextRules(L"execute=command",&rules.rules,&error),L"empty and executable/unknown text rules are refused");
    WorkspaceEntry entry; entry.left = path.wstring(); entry.hex_bookmarks = bookmarks.Save(false); entry.table_rules = L"header=yes\n1,1,key"; entry.text_rules = L"ignore-blank=yes\n"; const auto workspace = root / L"features.ini"; std::vector<WorkspaceEntry> entries; check(SaveWorkspaceFile(workspace,{entry},&error) && LoadWorkspaceFile(workspace,&entries,&error) && entries[0].table_rules == entry.table_rules && entries[0].text_rules == entry.text_rules && entries[0].hex_bookmarks == entry.hex_bookmarks,L"workspaces retain bounded feature settings alongside the original session fields");
    return failures;
}
